const STORE='field-index-v1';
const emptyState=()=>({viewed:{},pinned:{},comparisons:{},notes:{},conclusions:{},conclusionHistory:{},activeCase:null,reopened:{},release:{stage:0,relation:'',reason:'',saved:false},weather:[],motionChecked:false,claimsChecked:false});
let state=loadState();
let view={name:'index',caseId:null};
const main=document.querySelector('#main'),desk=document.querySelector('#deskPanel'),deskContent=document.querySelector('#deskContent'),toast=document.querySelector('#toast');
function loadState(){try{return Object.assign(emptyState(),JSON.parse(localStorage.getItem(STORE)||'{}'))}catch{return emptyState()}}
function save(){localStorage.setItem(STORE,JSON.stringify(state));renderDesk()}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function showToast(text){toast.textContent=text;toast.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>toast.classList.remove('show'),1800)}
function setStatus(text){document.querySelector('#statusText').textContent=text}
function navigate(name,caseId=null){view={name,caseId};document.querySelectorAll('.rail-button').forEach(b=>b.classList.toggle('active',b.dataset.view===name||(name==='case'&&b.dataset.view==='index')));render();window.scrollTo(0,0);main.focus()}
function caseById(id){return CASES.find(c=>c.id===id)}
function recordById(id){for(const c of CASES){const r=c.records.find(x=>x.id===id);if(r)return {...r,caseId:c.id,caseTitle:c.title}}}
function icon(type){return({video:'VID',image:'IMG',document:'DOC',analysis:'ANA',data:'DAT',audio:'AUD'})[type]||'REC'}
function progress(c){const v=c.records.filter(r=>state.viewed[r.id]).length;const compared=(state.comparisons[c.id]||[]).length;return {v,compared,done:!!state.conclusions[c.id]}}
function render(){if(view.name==='index')renderIndex();else if(view.name==='case')renderCase(view.caseId);else if(view.name==='release')renderRelease();else renderMethods();renderDesk()}
function renderIndex(){setStatus('Eight launch files available');main.innerHTML=`<section class="page"><div class="hero"><div><span class="eyebrow">ARCHIVE INVESTIGATION / LAUNCH DESK</span><h1>Read the record.<br>Mark the boundary.</h1><p>Eight public-record cases. Inspect provenance, compare claims, and write conclusions that say what the evidence cannot establish. The desk preserves your work; it never assigns a hidden answer.</p></div><div class="hero-note"><span class="eyebrow">DESK PRINCIPLE 01</span><strong>Authentic file ≠ confirmed explanation</strong><p>Official publication can establish custody or release history. It does not, on its own, identify what an image depicts.</p></div></div><div class="section-head"><div><span class="eyebrow">LAUNCH COLLECTION</span><h2>Case files</h2></div><p>Early files foreground fixed references and provenance. Later files leave the comparison strategy to you.</p></div><div class="case-grid">${CASES.map(caseCard).join('')}</div></section>`;main.querySelectorAll('.open-case').forEach(b=>b.onclick=()=>navigate('case',b.dataset.case));}
function caseCard(c){const p=progress(c);return `<article class="case-card" data-testid="case-card-${c.id}">${state.reopened[c.id]?'<span class="reopened-ribbon">REOPENED</span>':''}<span class="eyebrow">${c.tag}</span><div class="year">${c.year}</div><h3>${c.title}</h3><p>${c.place}</p><p style="margin-top:10px">${c.synopsis}</p><div class="card-bottom"><span class="record-count">${p.v}/${c.records.length} VIEWED · ${p.compared} COMPARED</span><span class="state-dots"><i class="${p.v?'on':''}"></i><i class="${p.compared?'on':''}"></i><i class="${p.done?'on':''}"></i></span></div><button class="open-case" data-case="${c.id}" data-testid="open-case-${c.id}">Open ${c.title}</button></article>`}
function renderCase(id){const c=caseById(id);state.activeCase=id;save();setStatus(`${c.year} ${c.title} open`);main.innerHTML=`<header class="case-header"><div class="case-title"><button class="back-link" data-testid="back-index">← Case index</button><span class="eyebrow">CASE ${c.year} / ${c.tag}</span><h1>${c.title}</h1><p>${c.synopsis}</p><div class="meta-row"><span class="chip">${c.place}</span><span class="chip">${c.records.length} RECORDS</span><span class="chip">${c.level.toUpperCase()}</span>${state.reopened[id]?'<span class="chip">REOPENED BY NEW RECORD</span>':''}</div></div></header><div class="case-layout"><section><div class="panel"><span class="eyebrow">INVESTIGATION QUESTION</span><div class="question">${c.question}</div><div class="section-head"><div><h2>Source register</h2></div><span class="record-count">VIEW · PIN · COMPARE</span></div><div class="records">${c.records.map(r=>recordRow(c,r)).join('')}</div></div>${id==='aguadilla'?aguadillaLab():''}</section><aside><div class="panel"><span class="eyebrow">COMPARISON TRAY</span><h2>Set records side by side</h2><div id="compareArea">${comparisonArea(c)}</div></div><div class="panel" style="margin-top:14px"><span class="eyebrow">CASE NOTEBOOK</span><h2>Bounded conclusion</h2><div id="notebookArea">${notebook(c)}</div></div></aside></div>`;
bindCase(c)}
function recordRow(c,r){const pinned=!!state.pinned[r.id];return `<article class="record ${state.viewed[r.id]?'viewed':''}" data-testid="record-${r.id}"><div class="record-icon">${icon(r.type)}</div><div><h3>${r.title}</h3><p>${r.date} · ${r.source}</p></div><div class="record-actions"><button data-open="${r.id}" data-testid="view-${r.id}">${state.viewed[r.id]?'Reopen':'View'}</button><button data-pin="${r.id}" aria-pressed="${pinned}" aria-label="${pinned?'Unpin':'Pin'} ${r.title}">${pinned?'Pinned':'Pin'}</button></div></article>`}
function bindCase(c){main.querySelector('[data-testid=back-index]').onclick=()=>navigate('index');main.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openRecord(b.dataset.open));main.querySelectorAll('[data-pin]').forEach(b=>b.onclick=()=>{state.pinned[b.dataset.pin]=!state.pinned[b.dataset.pin];save();renderCase(c.id)});bindComparison(c);bindNotebook(c);if(c.id==='aguadilla')bindAguadilla()}
function openRecord(id){const r=recordById(id);state.viewed[id]=true;save();const media=r.asset?`<div class="media">${r.type==='video'?`<video controls preload="metadata" data-testid="media-${id}"><source src="${r.asset}"></video>`:`<img src="${r.asset}" alt="${esc(r.title)}">`}</div>`:'';document.querySelector('#recordBody').innerHTML=`<article class="record-detail"><span class="eyebrow">${icon(r.type)} / ${r.date}</span><h1 id="recordTitle">${r.title}</h1><p>${r.note}</p>${media}<div class="sourcebox"><b>Source represented</b><br>${r.source}<br><br><b>Use in this prototype</b><br>${r.asset?'Local media is shown with manifest attribution.':'Authored summary only; the source file is not republished.'}</div></article>`;document.querySelector('#recordDialog').showModal();setStatus(`${r.title} viewed`);}
function comparisonArea(c){const selected=(state.notes[c.id]?.selected||[]).slice(0,2),a=recordById(selected[0]),b=recordById(selected[1]),hist=state.comparisons[c.id]||[];return `<div class="compare-slots"><div class="slot"><small>RECORD A</small>${a?esc(a.title):'Pin a record to compare'}</div><div class="slot"><small>RECORD B</small>${b?esc(b.title):'Pin another record'}</div></div><div class="records">${c.records.map(r=>`<label class="record" style="min-height:50px;grid-template-columns:auto 1fr"><input type="checkbox" data-select="${r.id}" ${selected.includes(r.id)?'checked':''}><span>${r.title}</span></label>`).join('')}</div><label style="display:grid;gap:6px;margin-top:12px;font-size:11px;font-weight:700">What changes when these are read together?<textarea class="compare-note" data-testid="comparison-note" placeholder="Record the relationship, conflict, or limit…"></textarea></label><button class="primary" data-testid="save-comparison" style="margin-top:9px">Save comparison</button><div class="comparison-history">${hist.map(x=>`<div class="comparison-entry"><b>${esc(recordById(x.a)?.title||x.a)} ↔ ${esc(recordById(x.b)?.title||x.b)}</b><br>${esc(x.note)}</div>`).join('')}</div>`}
function bindComparison(c){const area=main.querySelector('#compareArea');area.querySelectorAll('[data-select]').forEach(x=>x.onchange=()=>{let s=(state.notes[c.id]?.selected||[]).filter(id=>id!==x.dataset.select);if(x.checked)s.push(x.dataset.select);s=s.slice(-2);state.notes[c.id]={...(state.notes[c.id]||{}),selected:s};save();area.innerHTML=comparisonArea(c);bindComparison(c)});area.querySelector('[data-testid=save-comparison]').onclick=()=>{const s=state.notes[c.id]?.selected||[],note=area.querySelector('textarea').value.trim();if(s.length!==2||!note)return showToast('Choose two records and write a comparison');state.comparisons[c.id]=[...(state.comparisons[c.id]||[]),{a:s[0],b:s[1],note,time:new Date().toISOString()}];s.forEach(id=>state.viewed[id]=true);save();renderCase(c.id);showToast('Comparison saved')};}

function notebook(c){const x=state.conclusions[c.id],hist=state.conclusionHistory[c.id]||[];if(x)return `<div class="saved-conclusion" data-testid="saved-conclusion"><span class="eyebrow">SAVED ${esc(x.savedAt)}</span><h3>${esc(x.position)}</h3><dl><dt>Support</dt><dd>${esc(x.support)}</dd><dt>Conflict</dt><dd>${esc(x.conflict)}</dd><dt>Weakness</dt><dd>${esc(x.weakness)}</dd><dt>Missing</dt><dd>${esc(x.missing)}</dd><dt>Revision trigger</dt><dd>${esc(x.trigger)}</dd></dl><button class="small-button" data-testid="revise-conclusion">Revise without erasing</button><div class="method-links">${METHODS.slice(0,3).map(m=>`<button data-method="${m.id}">${m.title}</button>`).join('')}</div></div>${hist.length?`<div class="history-list"><b>Earlier versions</b>${hist.map((h,i)=>`<div class="history-item">v${i+1} · ${esc(h.savedAt)} · ${esc(h.position)}</div>`).join('')}</div>`:''}`;return `<form class="notebook" data-testid="conclusion-form"><label>Current position<select name="position"><option>Evidence remains insufficient</option><option>Conventional explanation is plausible</option><option>Reported performance is not established</option><option>Phenomenon remains unidentified</option><option>Non-human origin is plausible but unproven</option></select></label><label>Strongest support<textarea name="support" required placeholder="Which record and what does it establish?"></textarea></label><label>Material conflict<textarea name="conflict" required placeholder="Which record or claim points another way?"></textarea></label><label>Weakest link<textarea name="weakness" required placeholder="Where does your inference rely on an assumption?"></textarea></label><label>Missing information<textarea name="missing" required placeholder="What cannot this record set tell you?"></textarea></label><label>What would make you revise?<textarea name="trigger" required placeholder="Name a concrete new observation or record."></textarea></label><button class="primary" type="submit" data-testid="save-conclusion">Save conclusion</button></form>`}
function bindNotebook(c){const area=main.querySelector('#notebookArea'),form=area.querySelector('form');if(form)form.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form));if(Object.values(d).some(v=>!v.trim()))return;const previous=state.conclusions[c.id];if(previous)state.conclusionHistory[c.id]=[...(state.conclusionHistory[c.id]||[]),previous];state.conclusions[c.id]={...d,savedAt:new Date().toLocaleString('en-US',{dateStyle:'medium',timeStyle:'short'})};save();renderCase(c.id);showToast('Conclusion saved to the desk')};area.querySelector('[data-testid=revise-conclusion]')?.addEventListener('click',()=>{const old=state.conclusions[c.id];state.conclusionHistory[c.id]=[...(state.conclusionHistory[c.id]||[]),old];delete state.conclusions[c.id];save();renderCase(c.id)});area.querySelectorAll('[data-method]').forEach(b=>b.onclick=()=>navigate('methods'))}
function aguadillaLab(){const rows=[['2013-04-26 21:50','060°','11 kt','12.7 mph','3h32m before'],['2013-04-26 22:50','060°','10 kt gust 14','11.5 mph · gust 16.1','2h32m before'],['2013-04-26 23:50','060°','9 kt','10.4 mph','1h32m before']];return `<div class="panel" style="margin-top:14px" data-testid="aguadilla-lab"><span class="eyebrow">FIELD CHECK / WEATHER & MOTION</span><h2>Test the reported drift</h2><p class="muted">The event occurred 26 April 2013 at 9:22 p.m. local, which is 27 April 01:22 UTC. AARO assesses object motion at 3.6 m/s (8 mph), citing recorded wind at 4.4 m/s (9.8 mph) from east/northeast.</p><table class="weather-table"><thead><tr><th>Select</th><th>UTC observation</th><th>Wind from</th><th>Speed</th><th>Event offset</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="${state.weather.includes(i)?'selected':''}"><td><button data-weather="${i}" aria-pressed="${state.weather.includes(i)}">${state.weather.includes(i)?'Selected':'Use'}</button></td><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]}<br>${r[3]}</td><td>${r[4]}</td></tr>`).join('')}</tbody></table><div id="weatherFinding">${weatherFinding(rows)}</div><div class="claim-grid"><div class="claim"><b>AARO reconstruction</b>Observer arcs and climbs; range nearly triples. Assessed objects remain over land at wind-like speed.</div><div class="claim"><b>SCU response</b>Argues line-of-sight matching requires at least 16.6 mph and that disappearance supports water entry.</div><div class="claim"><b>Lianza / IPACO</b>Argues parallax invalidates screen-speed inference and proposes paired wind-driven lanterns.</div></div><button class="small-button" data-testid="check-motion">${state.motionChecked?'Motion comparison recorded':'Compare frames & platform motion'}</button><button class="small-button" data-testid="check-claims">${state.claimsChecked?'Claim dispute recorded':'Map separation & transmedium claims'}</button>${state.motionChecked?'<p class="finding" data-testid="motion-finding">The aircraft’s arc, climb, zoom, and changing range can create apparent ground speed. That weakens direct screen-speed inference; it does not by itself identify the objects.</p>':''}${state.claimsChecked?'<p class="finding" data-testid="claims-finding">The sources dispute scene geometry: AARO models two nearby objects repeatedly separating at 00:29.56, 00:40.76, and 00:47.00 and remaining over land; SCU interprets occlusion and thermal changes as tree/water interaction. Compare model inputs before treating either rendering as direct observation.</p>':''}</div>`}
function weatherFinding(rows){if(state.weather.length<3){const picked=state.weather.map(i=>`${rows[i][0].slice(11)} is ${rows[i][4]}`).join('; ');return `<p class="finding">Select the three latest observations in the bundled extract.${picked?` Selected so far: ${picked}.`:''}</p>`}return `<p class="finding" data-testid="weather-gap"><b>Timing check:</b> 21:50, 22:50, and 23:50 UTC are respectively 3h32m, 2h32m, and 1h32m before the 27 April 01:22 UTC event. <b>Coverage gap:</b> the extract ends at 23:50 UTC and contains no post-event observation, so it does not bracket the event. AARO’s exact 4.4 m/s is about 8.6 kt; none of these airport rows directly reproduces that value or measures conditions aloft at the modeled object position.</p>`}
function bindAguadilla(){main.querySelectorAll('[data-weather]').forEach(b=>b.onclick=()=>{const i=+b.dataset.weather;state.weather=state.weather.includes(i)?state.weather.filter(x=>x!==i):[...state.weather,i];save();renderCase('aguadilla')});main.querySelector('[data-testid=check-motion]').onclick=()=>{state.motionChecked=true;save();renderCase('aguadilla')};main.querySelector('[data-testid=check-claims]').onclick=()=>{state.claimsChecked=true;save();renderCase('aguadilla')}}
function renderRelease(){setStatus(`${RELEASE.recordId} intake open`);const s=state.release;main.innerHTML=`<header class="release-header"><div class="release-title"><button class="back-link" data-testid="back-index">← Case index</button><span class="eyebrow">PURSUE INTAKE / ${RELEASE.releaseId.toUpperCase()}</span><h1>One film, another release.</h1><p>A newly received record matches a known date and place. Establish the version relationship before deciding what the release adds to the archive.</p><div class="meta-row"><span class="chip">${RELEASE.recordId}</span><span class="chip">UNPROCESSED</span><span class="chip">LOCAL MEDIA</span></div></div></header><div class="case-layout"><section><div class="panel"><span class="eyebrow">RECORD INTAKE</span><h2>${RELEASE.title}</h2>${releaseMeta()}<video controls preload="metadata" style="width:100%;background:#111" data-testid="pr159-player"><source src="${RELEASE.asset}"></video><button class="primary" data-testid="inspect-release" style="margin-top:12px">${s.stage>=1?'Metadata inspected':'Inspect media & provenance'}</button></div>${s.stage>=1?releaseCompare():''}</section><aside><div class="panel"><span class="eyebrow">RELATIONSHIP DECISION</span><h2>What does this record add?</h2>${s.stage>=2?releaseDecision():`<p class="muted">Inspect the record, then compare it with the historical case representation.</p>`}</div>${s.saved?releaseResult():''}</aside></div>`;bindRelease()}
function releaseMeta(){return `<div class="release-meta" data-testid="release-metadata"><div><small>RECORD</small><b>${RELEASE.recordId}</b></div><div><small>PUBLISHED TITLE</small><b>${RELEASE.title}</b></div><div><small>INCIDENT</small><b>${RELEASE.incidentDate}</b></div><div><small>LOCATION</small><b>${RELEASE.location}</b></div><div><small>FILE</small><b>${RELEASE.file}</b></div><div><small>TECHNICAL</small><b>${RELEASE.format} · ${RELEASE.dimensions} · ${RELEASE.duration}</b></div><div><small>SIZE</small><b>${RELEASE.size}</b></div><div><small>DVIDS ID</small><b>${RELEASE.dvids}</b></div><div><small>SHA-256</small><b>${RELEASE.sha256}</b></div></div>`}
function releaseCompare(){return `<div class="panel" style="margin-top:14px" data-testid="version-comparison"><span class="eyebrow">SYNCHRONIZED VERSION CHECK</span><h2>PR159 ↔ historical representation</h2><div class="dual-player"><div><small class="mono">PR159 · 1920×1080 · 70.083 s</small><video controls preload="metadata" data-sync-player="new"><source src="${RELEASE.asset}"></video></div><div><small class="mono">LATER REPRESENTATION · 1280×720 · 70.070 s</small><video controls preload="metadata" data-sync-player="old"><source src="assets/tremonton-reference.mp4"></video></div></div><div class="sync-controls"><button class="small-button" data-testid="sync-play">Play / pause both</button><label>Seek together <input data-testid="sync-seek" type="range" min="0" max="69" step="1" value="18"></label><output data-testid="sync-time">00:18</output></div><div class="version-grid"><div><b>Content relationship</b><br>Same incident date, place, approximate running time, and matching film imagery.</div><div><b>Version differences</b><br>PR159 is a 1920×1080 DoW/DVIDS release record; the case copy is a 1280×720 later news representation. Encode, frame, labels, and chain of publication can differ.</div></div><button class="primary" data-testid="complete-version-compare">Record version comparison</button></div>`}
function releaseDecision(){const s=state.release;return `<form class="release-form" data-testid="release-form"><div class="relation-options"><label><input type="radio" name="relation" value="same-version" ${s.relation==='same-version'?'checked':''}> Same underlying film, different version<span class="consequence">Links provenance and version history. Independent corroboration does not increase.</span></label><label><input type="radio" name="relation" value="new-evidence" ${s.relation==='new-evidence'?'checked':''}> Independent evidence of same event<span class="consequence">Would add corroboration only if separately created, not merely re-encoded.</span></label><label><input type="radio" name="relation" value="unresolved" ${s.relation==='unresolved'?'checked':''}> Relationship unresolved<span class="consequence">Holds the record apart until custody or content can be matched.</span></label></div><label>Relationship reason<textarea name="reason" required data-testid="relationship-reason" placeholder="Cite the matching content and version differences…">${esc(s.reason)}</textarea></label><button class="primary" type="submit" data-testid="save-relationship">Save archive relationship</button></form>`}
function releaseResult(){return `<div class="panel release-result" style="margin-top:14px" data-testid="release-result"><span class="eyebrow">ARCHIVE UPDATED</span><h2>Tremonton reopened</h2><p>PR159 is attached as a new publication version of the same underlying historical film. Independent corroboration does not increase; the release strengthens provenance and access history.</p><div class="timeline"><div><b>1952</b> Underlying 16 mm film recorded.</div><div><b>1968</b> Condon Case 49 publishes a later analysis.</div><div><b>2026</b> PR159 release adds DoW/DVIDS publication metadata and another file version.</div></div><button class="primary" data-testid="reopen-tremonton">Open preserved Tremonton conclusion</button></div>`}
function bindRelease(){main.querySelector('[data-testid=back-index]').onclick=()=>navigate('index');main.querySelector('[data-testid=inspect-release]').onclick=()=>{state.release.stage=Math.max(1,state.release.stage);save();renderRelease()};if(state.release.stage>=1){const players=[...main.querySelectorAll('[data-sync-player]')],slider=main.querySelector('[data-testid=sync-seek]'),out=main.querySelector('[data-testid=sync-time]');slider.oninput=()=>{players.forEach(v=>v.currentTime=+slider.value);out.value=`00:${String(slider.value).padStart(2,'0')}`};main.querySelector('[data-testid=sync-play]').onclick=()=>players.forEach(v=>v.paused?v.play().catch(()=>{}):v.pause());main.querySelector('[data-testid=complete-version-compare]').onclick=()=>{state.release.stage=2;save();renderRelease()}}if(state.release.stage>=2){const form=main.querySelector('[data-testid=release-form]');form.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form));if(!d.relation||!d.reason.trim())return showToast('Select a relationship and explain why');state.release={...state.release,relation:d.relation,reason:d.reason,saved:true};if(d.relation==='same-version'){state.reopened.tremonton=true;state.pinned['tr-film']=true}save();renderRelease();showToast('Archive relationship saved')}}main.querySelector('[data-testid=reopen-tremonton]')?.addEventListener('click',()=>navigate('case','tremonton'))}
function renderMethods(){setStatus('Methods index open');main.innerHTML=`<section class="page"><div class="hero"><div><span class="eyebrow">TRANSFERABLE PRACTICE</span><h1>Methods, not verdicts.</h1><p>Saved work links to repeatable checks. A method can narrow a claim without deciding the identity of an object.</p></div><div class="hero-note"><span class="eyebrow">DESK PRINCIPLE 02</span><strong>Preserve uncertainty precisely</strong><p>“Unidentified” describes the present record. It does not name an origin.</p></div></div><div class="method-grid">${METHODS.map((m,i)=>`<article class="method-card" id="${m.id}"><span class="number">0${i+1}</span><h2>${m.title}</h2><p>${m.text}</p></article>`).join('')}</div></section>`}
function renderDesk(){const active=state.activeCase?caseById(state.activeCase):null,pins=Object.keys(state.pinned).filter(k=>state.pinned[k]),done=Object.keys(state.conclusions);deskContent.innerHTML=`${active?`<div class="desk-case"><small>ACTIVE CASE</small><b>${active.year} ${active.title}</b></div>`:''}<div class="desk-case"><small>PINNED RECORDS</small><b>${pins.length}</b>${pins.slice(0,5).map(id=>`<small>${esc(recordById(id)?.title||id)}</small>`).join('<br>')}</div><div class="desk-case"><small>SAVED CONCLUSIONS</small><b>${done.length}</b>${done.map(id=>`<small>${caseById(id)?.title}</small>`).join('<br>')}</div><div class="desk-case"><small>INCOMING RECORD</small><b>${state.release.saved?'Relationship filed':'PR159 awaiting decision'}</b></div>`}
function exportState(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='field-index-desk.json';a.click();URL.revokeObjectURL(a.href)}
function init(){document.querySelector('[data-testid=home-button]').onclick=()=>navigate('index');document.querySelectorAll('.rail-button').forEach(b=>b.onclick=()=>navigate(b.dataset.view));document.querySelector('[data-testid=desk-menu]').onclick=()=>{desk.classList.toggle('open');document.querySelector('[data-testid=desk-menu]').setAttribute('aria-expanded',desk.classList.contains('open'))};document.querySelector('[data-testid=close-desk]').onclick=()=>desk.classList.remove('open');document.querySelector('[data-testid=close-record]').onclick=()=>document.querySelector('#recordDialog').close();document.querySelector('[data-testid=reset-state]').onclick=()=>document.querySelector('#resetDialog').showModal();document.querySelector('[data-testid=cancel-reset]').onclick=()=>document.querySelector('#resetDialog').close();document.querySelector('[data-testid=confirm-reset]').onclick=()=>{state=emptyState();save();document.querySelector('#resetDialog').close();desk.classList.remove('open');navigate('index');showToast('Desk history cleared')};document.querySelector('[data-testid=export-state]').onclick=exportState;document.querySelector('[data-testid=import-state]').onchange=async e=>{try{state=Object.assign(emptyState(),JSON.parse(await e.target.files[0].text()));save();render();showToast('Desk history imported')}catch{showToast('That file could not be imported')}};render()}
init();
